fetch("/api/presensi/jdldns",{method:"GET"}).then(t=>{if(!t.ok)throw t;return t.json()}).then(t=>{let e=document.getElementById("typeShift");e.innerHTML=t.data.dnsType.type;let n=document.getElementById("MasukShift");n.innerHTML=t.data.dnsType.start_min+" - "+t.data.dnsType.start_max;let d=document.getElementById("PulangShift");d.innerHTML=t.data.dnsType.end_min+" - "+t.data.dnsType.end_max});
